1	// Helpers for checks that scan source *code* for a forbidden token (a banned
2	// API, an impure import, a DOM specific). Such a check must see code, not
3	// prose: a comment or a doc-string that merely *names* `chrome.storage` or
4	// `fetch(` is describing the code, not doing it, and matching it is a false
5	// positive that fails the build over an English sentence. Strip comments first.
6	
7	// Return `source` with its JS/TS comments removed, leaving everything else —
8	// including string and template literals — byte-for-byte intact. String-aware
9	// on purpose: a `//` inside "https://…" is not a comment, and dropping the rest
10	// of that line would corrupt real code (and could hide a genuine violation that
11	// follows on the same line). Regex literals are treated as code and preserved.
12	// Newlines inside block comments are kept so line numbers don't shift.
13	export function stripComments(source) {
14	  let out = '';
15	  let state = 'code'; // code | line | block | sq | dq | tpl
16	  for (let i = 0; i < source.length; i++) {
17	    const c = source[i];
18	    const c2 = source[i + 1];
19	    if (state === 'code') {
20	      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
21	      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
22	      if (c === "'") state = 'sq';
23	      else if (c === '"') state = 'dq';
24	      else if (c === '`') state = 'tpl';
25	      out += c;
26	    } else if (state === 'line') {
27	      if (c === '\n') { state = 'code'; out += c; }
28	    } else if (state === 'block') {
29	      if (c === '*' && c2 === '/') { state = 'code'; i++; }
30	      else if (c === '\n') out += c;
31	    } else {
32	      // Inside a string/template literal: copy through until the matching quote,
33	      // honoring backslash escapes so an escaped quote doesn't end it early.
34	      out += c;
35	      if (c === '\\') { out += c2 ?? ''; i++; }
36	      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
37	        state = 'code';
38	      }
39	    }
40	  }
41	  return out;
42	}
43	
44	// The extensions whose comments `stripComments` actually models. A file outside
45	// this set is never called comments-only: the parser cannot see its comments, so
46	// "nothing but comments changed" is a claim it has no grounds for, and answering
47	// "no" is the end that fails safe for both callers below.
48	export const COMMENT_CHECKABLE = new Set([
49	  '.mjs', '.cjs', '.js', '.jsx', '.ts', '.tsx', '.c', '.h', '.cc', '.cpp', '.hpp',
50	  '.java', '.go', '.swift', '.kt', '.dart', '.rs', '.cs', '.scss', '.css',
51	]);
52	
53	// Did a change to `file` touch only its comments? `before`/`after` are the file's
54	// two contents, null where it was added or deleted — neither of which is a
55	// comment-only change, whatever the other side holds.
56	//
57	// Indentation and blank lines are ignored, so a whitespace-only edit inside a
58	// template literal reads as comments-only; in a language whose indentation is
59	// semantic the extension set above has already answered no.
60	//
61	// Its callers grant a PERMISSION on the answer — may this run land its own pull
62	// request unreviewed, may it have touched this file at all — which is why the safe
63	// end is "no" and why the answer lives here rather than in each of them.
64	export function commentOnly(file, before, after) {
65	  if (before == null || after == null) return false;
66	  const dot = file.lastIndexOf('.');
67	  const ext = dot === -1 ? '' : file.slice(dot).toLowerCase();
68	  if (!COMMENT_CHECKABLE.has(ext)) return false;
69	  const meat = (text) => stripComments(text).split('\n').map((l) => l.trim()).filter((l) => l !== '').join('\n');
70	  return meat(before) === meat(after);
71	}
